     {
         kernel << other.kernel.rdbuf();
         config = other.config;
         return *this;
     }

 #   if __cplusplus >= 201103L
     /// Constructor (move)
     gsJITCompiler(gsJITCompiler && other)
     : //kernel(std::move(other.kernel)),
