     const short_t d = static_cast<short_t>(numNodes.rows());
     static const T epsilon = std::pow(10.0, -REAL_DIG * 0.85);
     // Get base rule nodes and weights
     std::vector<gsVector<T> > nodes(d);
     std::vector<gsVector<T> > weights(d);

