  T maxUniformity = ev.max(metric_Uniformity);
  T integralUniformity = ev.integral(metric_Uniformity);
  gsInfo << " Uniformity:    min.: " << minUniformity
         << "    max: " << maxUniformity
         << "    integral: " << integralUniformity / mp.nPatches() << "\n";
}

