     {
         internal::ElementBlock ElBlock = pair.second;

         gsKnotVector<> kv1(0,1,0,ElBlock.PR+1); 
         gsKnotVector<> kv2(0,1,0,ElBlock.PS+1);
         // coefs.setZero( (ElBlock.PR+1)*(ElBlock.PS+1), controlPoints.cols()-1 );

