     template<typename T>                                                \
     class gsname : public gsSparseSolver<T>, public gsEigenAdaptor<T>::eigenName \
     {                                                                   \
         typedef typename gsSparseSolver<T>::MatrixT MatrixT;            \
         typedef typename gsSparseSolver<T>::VectorT VectorT;            \
