         bool succeed() const                                            \
         {                                                               \
             return gsEigenAdaptor<T>::eigenName::info()==Eigen::Success;\
         }                                                               \
         index_t rows() const {return m_rows;}                           \
         index_t cols() const {return m_cols;}                           \
         std::ostream &print(std::ostream &os) const                     \
         {                                                               \
-            os <<STRINGIFY(gsname)<<"\n";                               \
