int fromTensorIndex(const gsVector<unsigned, d>& idx, const gsVector<unsigned, d>& sz)
{
    int result = 0;
    unsigned stride = 1;
    for (index_t i = 0; i < idx.size(); ++i)
    {
        result += stride * idx[i];
        stride *= sz[i];
    }
    return result;
}

