     for ( iiterator it = iBegin(); it != iEnd(); ++it ) // for all interfaces
     {
         const gsGeometry<T> & p1 = *m_patches[it->first() .patch];
         const gsGeometry<T> & p2 = *m_patches[it->second().patch];
         m_ifaces[*it] = p1.iface(*it,p2);
     }//end for
 }

 template<class T>
