 {
     m_bdr.clear();
     for ( biterator it = bBegin(); it != bEnd(); ++it ) // for all boundaries
     {
         const gsGeometry<T> & p1 = *m_patches[it->patch];
         m_bdr[*it] = p1.boundary(*it);
     }//end for
 }

