 {
     gsMesh<T> mesh;
     mesh.reserve(3 * m_mesh.getNumberOfTriangles(), m_mesh.getNumberOfTriangles(), 0);
     for (size_t i = 0; i < m_mesh.getNumberOfTriangles(); i++)
     {
         typename gsMesh<T>::VertexHandle v[3];
         for (size_t j = 1; j <= 3; ++j)
         {
